// ADD TO CART: Validate inputs and check stock
const input = $input.first().json.body || $input.first().json;
const customerId = input.customer_id;
const variantId = input.variant_id;
const quantity = parseInt(input.quantity) || 1;

if (!customerId || !variantId) {
  return [{ json: { error: true, message: 'customer_id and variant_id are required.' } }];
}
if (quantity < 1 || quantity > 10) {
  return [{ json: { error: true, message: 'Quantity must be between 1 and 10.' } }];
}

return [{ json: { customerId, variantId, quantity } }];

// Validate stock availability and prepare cart upsert
const variants = $input.first().json;
const variantArr = Array.isArray(variants) ? variants : [variants];
const validationData = $('Validate Add to Cart').first().json;
const requestedQty = validationData.quantity;
const customerId = validationData.customerId;

if (!variantArr || variantArr.length === 0 || !variantArr[0].id) {
  return [{ json: { success: false, error: 'Product variant not found or is inactive.' } }];
}

const variant = variantArr[0];
const available = variant.available_quantity - variant.reserved_quantity;

if (available < requestedQty) {
  return [{ json: { success: false, error: available > 0 ? `Only ${available} item(s) available.` : 'This item is currently out of stock.' } }];
}

const product = variant.products;
const unitPrice = product.sale_price || product.base_price;

return [{
  json: {
    success: true,
    customerId,
    variantId: variant.id,
    productId: variant.product_id,
    quantity: requestedQty,
    unitPrice,
    productName: product.name,
    size: variant.size,
    colour: variant.colour,
    currency: product.currency || 'LKR',
    imageUrl: (product.image_urls && product.image_urls.length > 0) ? product.image_urls[0] : null
  }
}];

// Format add-to-cart success response
const cartData = $('Verify Stock & Price').first().json;

return [{
  json: {
    success: true,
    message: `Added ${cartData.quantity}x ${cartData.productName} (${cartData.size}, ${cartData.colour}) to your cart.`,
    item: {
      product_name: cartData.productName,
      size: cartData.size,
      colour: cartData.colour,
      quantity: cartData.quantity,
      unit_price: cartData.unitPrice,
      currency: cartData.currency
    }
  }
}];

// GET CART: Retrieve current cart for customer
const input = $input.first().json.body || $input.first().json;
const customerId = input.customer_id;

if (!customerId) {
  return [{ json: { error: true, message: 'customer_id is required.' } }];
}

return [{ json: { customerId } }];

// Format the cart for display
const carts = $input.first().json;
const cartArr = Array.isArray(carts) ? carts : [carts];

if (!cartArr || cartArr.length === 0 || !cartArr[0].id) {
  return [{ json: { success: true, cart: { items: [], subtotal: 0, currency: 'LKR', message: 'Your cart is empty.' } } }];
}

const cart = cartArr[0];
const items = (cart.cart_items || []).map(item => {
  const product = item.products || {};
  const variant = item.product_variants || {};
  const available = (variant.available_quantity || 0) - (variant.reserved_quantity || 0);
  return {
    cart_item_id: item.id,
    product_name: product.name || 'Unknown',
    size: variant.size,
    colour: variant.colour,
    sku: variant.sku,
    quantity: item.quantity,
    unit_price: item.unit_price,
    line_total: item.quantity * item.unit_price,
    in_stock: available >= item.quantity
  };
});

const subtotal = items.reduce((sum, item) => sum + item.line_total, 0);

return [{
  json: {
    success: true,
    cart: {
      cart_id: cart.id,
      items,
      item_count: items.length,
      subtotal,
      currency: 'LKR',
      message: items.length > 0 ? `You have ${items.length} item(s) in your cart.` : 'Your cart is empty.'
    }
  }
}];

// CREATE ORDER: Validate all required order fields
const input = $input.first().json.body || $input.first().json;

const required = ['customer_id', 'customer_name', 'delivery_address', 'payment_method'];
const missing = required.filter(f => !input[f] || String(input[f]).trim() === '');

if (missing.length > 0) {
  return [{ json: { error: true, message: `Missing required fields: ${missing.join(', ')}` } }];
}

const validPaymentMethods = ['cash_on_delivery', 'bank_transfer'];
if (!validPaymentMethods.includes(input.payment_method)) {
  return [{ json: { error: true, message: `Invalid payment method. Accepted: ${validPaymentMethods.join(', ')}` } }];
}

return [{
  json: {
    customerId: input.customer_id,
    customerName: input.customer_name.trim(),
    deliveryAddress: input.delivery_address.trim(),
    contactNumber: (input.contact_number || '').trim(),
    paymentMethod: input.payment_method,
    notes: (input.notes || '').trim()
  }
}];

// Calculate order totals from current database prices (never trust client)
const carts = $input.first().json;
const cartArr = Array.isArray(carts) ? carts : [carts];
const orderData = $('Validate Order Data').first().json;

if (!cartArr || cartArr.length === 0 || !cartArr[0].cart_items || cartArr[0].cart_items.length === 0) {
  return [{ json: { error: true, message: 'Your cart is empty. Please add items before placing an order.' } }];
}

const cart = cartArr[0];
let subtotal = 0;
const orderItems = [];
const stockErrors = [];

for (const item of cart.cart_items) {
  const product = item.products || {};
  const variant = item.product_variants || {};
  const available = (variant.available_quantity || 0) - (variant.reserved_quantity || 0);

  if (available < item.quantity) {
    stockErrors.push(`${product.name} (${variant.size}/${variant.colour}): only ${available} available`);
    continue;
  }

  // Use current database price, not the cart's stored price
  const currentPrice = product.sale_price || product.base_price;
  const lineTotal = currentPrice * item.quantity;
  subtotal += lineTotal;

  orderItems.push({
    product_id: item.product_id,
    variant_id: item.variant_id,
    product_name: product.name,
    size: variant.size,
    colour: variant.colour,
    quantity: item.quantity,
    unit_price: currentPrice,
    total_price: lineTotal
  });
}

if (stockErrors.length > 0) {
  return [{ json: { error: true, message: `Some items are no longer available:\n${stockErrors.join('\n')}\nPlease update your cart.` } }];
}

// Delivery charge: free over 5000 LKR, otherwise 350 LKR
const deliveryCharge = subtotal >= 5000 ? 0 : 350;
const totalAmount = subtotal + deliveryCharge;

return [{
  json: {
    cartId: cart.id,
    customerId: orderData.customerId,
    customerName: orderData.customerName,
    deliveryAddress: orderData.deliveryAddress,
    contactNumber: orderData.contactNumber,
    paymentMethod: orderData.paymentMethod,
    notes: orderData.notes,
    items: orderItems,
    subtotal,
    deliveryCharge,
    discountAmount: 0,
    totalAmount,
    currency: 'LKR'
  }
}];

// Format the order confirmation response
const result = $input.first().json;
const orderData = $('Calculate Totals').first().json;

if (result.error || result.code) {
  return [{ json: { success: false, error: result.message || result.details || 'Failed to place order. Please try again.' } }];
}

const orderRef = result.order_ref || result;

return [{
  json: {
    success: true,
    order: {
      order_ref: orderRef,
      status: 'pending_confirmation',
      customer_name: orderData.customerName,
      delivery_address: orderData.deliveryAddress,
      payment_method: orderData.paymentMethod,
      items: orderData.items.map(i => ({
        name: i.product_name,
        size: i.size,
        colour: i.colour,
        quantity: i.quantity,
        unit_price: i.unit_price,
        total: i.total_price
      })),
      subtotal: orderData.subtotal,
      delivery_charge: orderData.deliveryCharge,
      discount: orderData.discountAmount,
      total: orderData.totalAmount,
      currency: orderData.currency
    },
    message: `Order ${orderRef} has been placed successfully! Status: Pending Confirmation.`
  }
}];

// GET ORDER STATUS
const input = $input.first().json.body || $input.first().json;
const orderRef = (input.order_ref || '').trim();
const customerId = input.customer_id;

if (!orderRef || !customerId) {
  return [{ json: { error: true, message: 'order_ref and customer_id are required.' } }];
}

return [{ json: { orderRef, customerId } }];

// Format order status response
const orders = $input.first().json;
const orderArr = Array.isArray(orders) ? orders : [orders];

if (!orderArr || orderArr.length === 0 || !orderArr[0].id) {
  return [{ json: { success: false, error: 'Order not found. Please check the order reference number.' } }];
}

const order = orderArr[0];
const statusLabels = {
  pending_confirmation: 'Pending Confirmation',
  confirmed: 'Confirmed',
  processing: 'Processing',
  packed: 'Packed',
  shipped: 'Shipped',
  delivered: 'Delivered',
  cancelled: 'Cancelled',
  return_requested: 'Return Requested'
};

return [{
  json: {
    success: true,
    order: {
      order_ref: order.order_ref,
      status: order.status,
      status_label: statusLabels[order.status] || order.status,
      customer_name: order.customer_name,
      delivery_address: order.delivery_address,
      payment_method: order.payment_method,
      items: (order.order_items || []).map(i => ({
        name: i.product_name,
        size: i.size,
        colour: i.colour,
        quantity: i.quantity,
        unit_price: i.unit_price,
        total: i.total_price
      })),
      subtotal: order.subtotal,
      delivery_charge: order.delivery_charge,
      discount: order.discount_amount,
      total: order.total_amount,
      currency: order.currency,
      placed_at: order.created_at,
      confirmed_at: order.confirmed_at,
      delivered_at: order.delivered_at
    }
  }
}];

// REMOVE FROM CART
const input = $input.first().json.body || $input.first().json;
const cartItemId = input.cart_item_id;
const customerId = input.customer_id;

if (!cartItemId || !customerId) {
  return [{ json: { error: true, message: 'cart_item_id and customer_id are required.' } }];
}

return [{ json: { cartItemId, customerId } }];
